def _print_json(data: Any) -> None:
    print(json.dumps(data, ensure_ascii=False, indent=2))


def _apply_mt_cli_args(target: dict[str, Any], args: argparse.Namespace) -> None:
    backend = getattr(args, "mt_backend", None)
    if backend:
        target["mtBackend"] = str(backend).strip()
    url = getattr(args, "mt_external_url", None)
    if url:
        ext = dict(target.get("mtExternal") or {}) if isinstance(target.get("mtExternal"), dict) else {}
        ext["url"] = str(url).strip()
        timeout = getattr(args, "mt_external_timeout", None)
        if timeout is not None:
            ext["timeoutSec"] = float(timeout)
        batch = getattr(args, "mt_external_batch", None)
        if batch is not None:
            ext["batchSize"] = int(batch)
        target["mtExternal"] = ext


def _add_mt_cli_args(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--mt-backend",
        default=None,
        choices=("opus-ct2", "external"),
        help="MT backend: local Opus (default) or external HTTP adapter",
    )
    parser.add_argument(
        "--mt-external-url",
        default=None,
        help="External MT adapter URL (required when --mt-backend=external)",
    )
    parser.add_argument(
        "--mt-external-timeout",
        type=float,
        default=None,
        help="External MT HTTP timeout seconds (default 120)",
    )
    parser.add_argument(
        "--mt-external-batch",
        type=int,
        default=None,
        help="External MT cue batch size (default 32)",
    )


def _progress_printer(mode: str):
    def on_progress(ev: dict[str, Any]) -> None:
        if mode == "text":
            stage = ev.get("stage") or ev.get("type")
            detail = ev.get("detail") or ev.get("message") or ""
            pct = ev.get("percent")
            if pct is not None:
                print(f"[{stage}] {pct}% {detail}", file=sys.stderr)
            else:
                print(f"[{stage}] {detail}", file=sys.stderr)
        else:
            print(json.dumps(ev, ensure_ascii=False), flush=True)

    return on_progress


def cmd_serve(args: argparse.Namespace) -> int:
    import uvicorn

    from .ffmpeg_util import ensure_ffmpeg_on_path
    from .logging_setup import configure_engine_logging
    from .runtime_gpu import inject_nvidia_lib_path, probe_gpu_runtime

    configure_engine_logging(quiet_access=True)

    ff = ensure_ffmpeg_on_path()
    if ff:
        print(f"[transub-engine] ffmpeg: {ff}", file=sys.stderr)
    else:
        print(
            "[transub-engine] ffmpeg not found "
            "(expected `_internal/bin/ffmpeg` next to the engine root, or FFMPEG_BINARY)",
            file=sys.stderr,
        )
    added = inject_nvidia_lib_path()
    gpu = probe_gpu_runtime()
    print(
        f"[transub-engine] gpu: status={gpu.get('status')} "
        f"name={gpu.get('gpuName') or '-'} cublas12={gpu.get('cublas12')} "
        f"ct2Cuda={gpu.get('ctranslate2Cuda')} "
        f"ortGpuCuda={gpu.get('ortGpuCuda')} "
        f"pathInjected={len(added)}",
        file=sys.stderr,
    )
    uvicorn.run(
        "transub_engine.server:app",
        host=args.host,
        port=args.port,
        log_level="info",
        access_log=True,
        # Default 5s drops keep-alive between long ASR jobs; Node fetch then
        # fails POST /v1/jobs with opaque "fetch failed" on the next item.
        timeout_keep_alive=75,
    )
    return 0


def cmd_health(_args: argparse.Namespace) -> int:
    _print_json(
        {
            "ok": True,
            "apiVersion": API_VERSION,
            "engineVersion": ENGINE_VERSION,
            "stub": is_stub_mode(),
        }
    )
    return 0


def cmd_capabilities(_args: argparse.Namespace) -> int:
    _print_json({"ok": True, **build_capabilities()})
    return 0


def cmd_models_list(_args: argparse.Namespace) -> int:
    _print_json({"ok": True, "models": list_models_status()})
    return 0


def cmd_models_recommend(args: argparse.Namespace) -> int:
    device = detect_device()
    rec = recommend_profile(
        vram_mb=int(args.vram_mb or device.get("vramMb") or 0),
        ram_mb=int(args.ram_mb or device.get("ramMb") or 0),
        has_cuda=bool(args.cuda if args.cuda is not None else device.get("hasCuda")),
    )
    _print_json({"ok": True, "device": device, **rec})
    return 0


def cmd_models_download(args: argparse.Namespace) -> int:
    ids = [x.strip() for x in (args.model or "").split(",") if x.strip()] or None
    try:
        result = download_models(
            profile=args.profile,
            model_ids=ids,
            on_progress=_progress_printer(args.progress),
        )
        if args.progress == "text":
            _print_json(result)
        return 0
    except Exception as err:
        print(json.dumps({"ok": False, "code": "DOWNLOAD_FAILED", "message": str(err)}), flush=True)
        return 1


def cmd_runtime_gpu(_args: argparse.Namespace) -> int:
    from .runtime_gpu import probe_gpu_runtime

    _print_json(probe_gpu_runtime())
    return 0


def cmd_runtime_ensure_gpu(args: argparse.Namespace) -> int:
    from .runtime_gpu import ensure_gpu_runtime

    result = ensure_gpu_runtime(
        force=bool(args.force),
        on_progress=_progress_printer(args.progress),
    )
    if args.progress == "text":
        _print_json(result)
    else:
        print(json.dumps(result, ensure_ascii=False), flush=True)
    return 0 if result.get("ok") else 1


