def cmd_run(args: argparse.Namespace) -> int:
    if getattr(args, "resume", None):
        from .jobs import JOBS

        try:
            # Sync resume via JobManager so job id / checkpoint wiring stays consistent
            job = JOBS.resume(args.resume, run_async=False)
            result = job.result
            if args.progress == "text":
                _print_json({"ok": True, "id": job.id, "resumedFrom": args.resume, "result": result})
            else:
                print(
                    json.dumps(
                        {
                            "type": "result",
                            "ok": True,
                            "id": job.id,
                            "resumedFrom": args.resume,
                            "result": result,
                        },
                        ensure_ascii=False,
                    )
                )
            return 0 if job.status == "done" else 1
        except Exception as err:
            print(
                json.dumps(
                    {"type": "error", "ok": False, "code": "RESUME_FAILED", "message": str(err)}
                ),
                flush=True,
            )
            return 1

    if args.job:
        # utf-8-sig tolerates Windows PowerShell BOM when saving job.json
        req = json.loads(Path(args.job).read_text(encoding="utf-8-sig"))
    else:
        req = {
            "task": args.task,
            "mediaPath": args.media,
            "outputDir": args.out,
            "language": args.language,
            "asrModel": args.asr_model,
            "mtModel": args.mt_model,
            "subFormats": [x.strip() for x in args.format.split(",") if x.strip()],
            "device": args.device,
            "includeWords": bool(getattr(args, "include_words", False)),
            "karaokeVtt": bool(getattr(args, "karaoke_vtt", False)),
        }
        if getattr(args, "perf_profile", None):
            req["perfProfile"] = str(args.perf_profile)
        _apply_mt_cli_args(req, args)
    try:
        result = execute_job(req, on_progress=_progress_printer(args.progress))
        if args.progress == "text":
            _print_json({"ok": True, "result": result})
        else:
            print(json.dumps({"type": "result", "ok": True, "result": result}, ensure_ascii=False))
        return 0
    except Exception as err:
        print(
            json.dumps({"type": "error", "ok": False, "code": "JOB_FAILED", "message": str(err)}),
            flush=True,
        )
        return 1


def cmd_batch(args: argparse.Namespace) -> int:
    from .batch import build_batch_requests
    from .jobs import JOBS

    paths = [x.strip() for x in (args.media or "").split(";") if x.strip()]
    if args.list_file:
        paths.extend(
            [
                ln.strip()
                for ln in Path(args.list_file).read_text(encoding="utf-8").splitlines()
                if ln.strip() and not ln.strip().startswith("#")
            ]
        )
    template = {
        "task": args.task,
        "language": args.language,
        "asrModel": args.asr_model,
        "device": args.device,
        "subFormats": [x.strip() for x in args.format.split(",") if x.strip()],
        "includeWords": bool(args.include_words),
        "karaokeVtt": bool(getattr(args, "karaoke_vtt", False)),
    }
    if args.out:
        template["outputDir"] = args.out
    if args.mt_model:
        template["mtModel"] = args.mt_model
    _apply_mt_cli_args(template, args)
    bid, reqs = build_batch_requests(paths, template=template, batch_id=args.batch_id)
    if not reqs:
        print(json.dumps({"ok": False, "code": "BATCH_EMPTY", "message": "no media"}), flush=True)
        return 1
    _, jobs = JOBS.create_batch(reqs, batch_id=bid, run_async=not args.sync)
    payload = {
        "ok": True,
        "batchId": bid,
        "count": len(jobs),
        "jobs": [{"id": j.id, "status": j.status, "mediaPath": j.request.get("mediaPath")} for j in jobs],
    }
    _print_json(payload)
    return 0


def cmd_scan_folder(args: argparse.Namespace) -> int:
    from .batch import build_batch_requests, scan_media_files
    from .jobs import JOBS

    try:
        files = scan_media_files(
            args.folder,
            recursive=not args.no_recursive,
            extensions=args.ext,
            limit=int(args.limit or 200),
        )
    except Exception as err:
        print(json.dumps({"ok": False, "code": "SCAN_FAILED", "message": str(err)}), flush=True)
        return 1
    template = {
        "task": args.task,
        "language": args.language,
        "asrModel": args.asr_model,
        "device": args.device,
        "subFormats": [x.strip() for x in args.format.split(",") if x.strip()],
        "includeWords": bool(args.include_words),
        "karaokeVtt": bool(getattr(args, "karaoke_vtt", False)),
    }
    if args.out:
        template["outputDir"] = args.out
    _apply_mt_cli_args(template, args)
    bid, reqs = build_batch_requests([str(p) for p in files], template=template)
    _, jobs = JOBS.create_batch(reqs, batch_id=bid, run_async=not args.sync)
    _print_json(
        {
            "ok": True,
            "batchId": bid,
            "scanned": len(files),
            "count": len(jobs),
            "jobs": [{"id": j.id, "mediaPath": j.request.get("mediaPath")} for j in jobs],
        }
    )
    return 0


def cmd_batch_status(args: argparse.Namespace) -> int:
    from .jobs import JOBS

    try:
        summary = JOBS.get_batch_summary(args.batch_id)
    except FileNotFoundError as err:
        print(json.dumps({"ok": False, "code": "BATCH_NOT_FOUND", "message": str(err)}), flush=True)
        return 1
    _print_json({"ok": True, **summary})
    return 0


def cmd_watch_start(args: argparse.Namespace) -> int:
    from .watch import WATCHES

    template = {
        "task": args.task,
        "language": args.language,
        "asrModel": args.asr_model,
        "device": args.device,
        "subFormats": [x.strip() for x in args.format.split(",") if x.strip()],
        "includeWords": bool(args.include_words),
        "karaokeVtt": bool(getattr(args, "karaoke_vtt", False)),
    }
    if args.mt_model:
        template["mtModel"] = args.mt_model
    _apply_mt_cli_args(template, args)
    try:
        state = WATCHES.start(
            folder=args.folder,
            recursive=not args.no_recursive,
            interval_s=float(args.interval or 15),
            extensions=[x.strip() for x in args.ext.split(",") if x.strip()] if args.ext else None,
            template=template,
            output_dir=args.out,
            settle_s=float(args.settle or 2),
            seed_existing=not args.no_seed,
        )
    except FileNotFoundError as err:
        print(json.dumps({"ok": False, "code": "WATCH_FAILED", "message": str(err)}), flush=True)
        return 1
    _print_json({"ok": True, "watch": WATCHES.get(state.id)})
    return 0


def cmd_watch_list(args: argparse.Namespace) -> int:
    from .watch import WATCHES

    _print_json({"ok": True, "watches": WATCHES.list()})
    return 0


def cmd_watch_stop(args: argparse.Namespace) -> int:
    from .watch import WATCHES

    ok = WATCHES.stop(args.watch_id)
    if not ok:
        print(
            json.dumps({"ok": False, "code": "WATCH_NOT_FOUND", "message": "watch not found"}),
            flush=True,
        )
        return 1
    _print_json({"ok": True, "stopped": True, "id": args.watch_id})
    return 0


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="transub-engine", description="Transub Engine CLI")
    sub = p.add_subparsers(dest="command", required=True)

    serve = sub.add_parser("serve", help="Start HTTP API")
    serve.add_argument("--host", default=DEFAULT_HOST)
    serve.add_argument("--port", type=int, default=DEFAULT_PORT)
    serve.set_defaults(func=cmd_serve)

    h = sub.add_parser("health", help="Print health JSON")
    h.set_defaults(func=cmd_health)

    c = sub.add_parser("capabilities", help="Print capabilities JSON")
    c.set_defaults(func=cmd_capabilities)

    models = sub.add_parser("models", help="Model management")
    models_sub = models.add_subparsers(dest="models_cmd", required=True)

    ml = models_sub.add_parser("list")
    ml.set_defaults(func=cmd_models_list)

    mr = models_sub.add_parser("recommend")
    mr.add_argument("--vram-mb", type=int, default=0)
    mr.add_argument("--ram-mb", type=int, default=0)
    mr.add_argument("--cuda", action="store_true", default=None)
    mr.add_argument("--no-cuda", action="store_false", dest="cuda")
    mr.set_defaults(func=cmd_models_recommend)

    md = models_sub.add_parser("download")
    md.add_argument("--profile", default=None)
    md.add_argument("--model", default="", help="Comma-separated model ids")
    md.add_argument("--progress", choices=("jsonl", "text"), default="jsonl")
    md.set_defaults(func=cmd_models_download)

    runtime = sub.add_parser("runtime", help="GPU / CUDA runtime helpers")
    runtime_sub = runtime.add_subparsers(dest="runtime_cmd", required=True)

    rg = runtime_sub.add_parser("gpu", help="Probe GPU + CUDA 12 runtime status")
    rg.set_defaults(func=cmd_runtime_gpu)

    re_ = runtime_sub.add_parser("ensure-gpu", help="Detect GPU and install CUDA 12 support wheels")
    re_.add_argument("--force", action="store_true", help="Reinstall even if already ready")
    re_.add_argument("--progress", choices=("jsonl", "text"), default="jsonl")
    re_.set_defaults(func=cmd_runtime_ensure_gpu)

    rw = runtime_sub.add_parser(
        "ensure-asr-whisper",
        help="Install faster-whisper / ctranslate2 / onnxruntime / av / numpy",
    )
    rw.add_argument(
        "--force",
        action="store_true",
        help="Force reinstall when metadata looks ok but imports fail (run with engine stopped)",
    )
    rw.add_argument("--progress", choices=("jsonl", "text"), default="jsonl")
    rw.set_defaults(func=cmd_runtime_ensure_asr_whisper)

    rsv = runtime_sub.add_parser(
        "ensure-asr-sensevoice",
        help="Install torch / funasr / numba / scipy / librosa for SenseVoice",
    )
    rsv.add_argument(
        "--force",
        action="store_true",
        help="Force reinstall when metadata looks ok but imports fail (run with engine stopped)",
    )
    rsv.add_argument("--progress", choices=("jsonl", "text"), default="jsonl")
    rsv.set_defaults(func=cmd_runtime_ensure_asr_sensevoice)

    run = sub.add_parser("run", help="Run one job synchronously")
    run.add_argument("--job", default=None, help="Path to job.json")
    run.add_argument("--resume", default=None, help="Resume from job id checkpoint")
    run.add_argument("--media", default=None)
    run.add_argument("--task", default="transcribe", choices=("transcribe", "translate_mt", "dual"))
    run.add_argument("--out", default=None)
    run.add_argument("--language", default="auto")
    run.add_argument("--asr-model", default="sensevoice-small")
    run.add_argument("--mt-model", default=None)
    _add_mt_cli_args(run)
    run.add_argument("--format", default="srt")
    run.add_argument("--device", default="auto")
    run.add_argument("--include-words", action="store_true")
    run.add_argument("--karaoke-vtt", action="store_true", help="Export karaoke WebVTT (implies word timings)")
    run.add_argument(
        "--perf-profile",
        choices=("quality", "speed"),
        default=None,
        help="quality (default) or speed (lighter VAD, skip retranscribe, faster Whisper)",
    )
    run.add_argument("--progress", choices=("jsonl", "text"), default="jsonl")
    run.set_defaults(func=cmd_run)

    batch = sub.add_parser("batch", help="Enqueue multiple media files")
    batch.add_argument("--media", default="", help="Semicolon-separated media paths")
    batch.add_argument("--list-file", default=None, help="Text file with one media path per line")
    batch.add_argument("--task", default="transcribe", choices=("transcribe", "translate_mt", "dual"))
    batch.add_argument("--out", default=None)
    batch.add_argument("--language", default="auto")
    batch.add_argument("--asr-model", default="sensevoice-small")
    batch.add_argument("--mt-model", default=None)
    _add_mt_cli_args(batch)
    batch.add_argument("--format", default="srt")
    batch.add_argument("--device", default="auto")
    batch.add_argument("--include-words", action="store_true")
    batch.add_argument("--karaoke-vtt", action="store_true")
    batch.add_argument("--batch-id", default=None)
    batch.add_argument("--sync", action="store_true", help="Run all jobs sequentially in this process")
    batch.set_defaults(func=cmd_batch)

    bs = sub.add_parser("batch-status", help="Show progress summary for a batch id")
    bs.add_argument("--batch-id", required=True)
    bs.set_defaults(func=cmd_batch_status)

    scan = sub.add_parser("scan-folder", help="Scan a folder and enqueue media as jobs")
    scan.add_argument("--folder", required=True)
    scan.add_argument("--no-recursive", action="store_true")
    scan.add_argument("--ext", default=None, help="Comma-separated extensions, e.g. mkv,mp4,wav")
    scan.add_argument("--limit", type=int, default=200)
    scan.add_argument("--task", default="transcribe", choices=("transcribe", "translate_mt", "dual"))
    scan.add_argument("--out", default=None)
    scan.add_argument("--language", default="auto")
    scan.add_argument("--asr-model", default="sensevoice-small")
    _add_mt_cli_args(scan)
    scan.add_argument("--format", default="srt")
    scan.add_argument("--device", default="auto")
    scan.add_argument("--include-words", action="store_true")
    scan.add_argument("--karaoke-vtt", action="store_true")
    scan.add_argument("--sync", action="store_true")
    scan.set_defaults(func=cmd_scan_folder)

    watch = sub.add_parser("watch", help="Folder watch daemon (poll + enqueue)")
    watch_sub = watch.add_subparsers(dest="watch_cmd", required=True)

    ws = watch_sub.add_parser("start", help="Start watching a folder for new media")
    ws.add_argument("--folder", required=True)
    ws.add_argument("--no-recursive", action="store_true")
    ws.add_argument("--interval", type=float, default=15.0, help="Poll interval seconds")
    ws.add_argument("--settle", type=float, default=2.0, help="Ignore files newer than N seconds")
    ws.add_argument("--ext", default=None, help="Comma-separated extensions")
    ws.add_argument("--no-seed", action="store_true", help="Do not seed seen-set; enqueue existing files on first scan")
    ws.add_argument("--task", default="transcribe", choices=("transcribe", "translate_mt", "dual"))
    ws.add_argument("--out", default=None)
    ws.add_argument("--language", default="auto")
    ws.add_argument("--asr-model", default="sensevoice-small")
    ws.add_argument("--mt-model", default=None)
    _add_mt_cli_args(ws)
    ws.add_argument("--format", default="srt")
    ws.add_argument("--device", default="auto")
    ws.add_argument("--include-words", action="store_true")
    ws.add_argument("--karaoke-vtt", action="store_true")
    ws.set_defaults(func=cmd_watch_start)

    wl = watch_sub.add_parser("list", help="List active watches")
    wl.set_defaults(func=cmd_watch_list)

    wx = watch_sub.add_parser("stop", help="Stop a watch by id")
    wx.add_argument("--watch-id", required=True)
    wx.set_defaults(func=cmd_watch_stop)

    return p


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    if args.command == "run" and not args.job and not args.media and not getattr(args, "resume", None):
        parser.error("run requires --job, --media, or --resume")
    return int(args.func(args) or 0)


if __name__ == "__main__":
    raise SystemExit(main())
